    12	import com.fasterxml.jackson.databind.ObjectMapper;
    13	import com.fasterxml.jackson.databind.SerializationFeature;
    14	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
    15	import io.javalin.Javalin;
    16	import io.javalin.http.Context;
    17	
    18	import java.util.Map;
    19	import java.util.function.Function;
    20	
    21	public final class Api {
    22	    private final ObjectMapper mapper = new ObjectMapper()
    23	            .registerModule(new JavaTimeModule())
    24	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    25	            .enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN);
    26	    private final Db db;
    27	    private final ReservationService service;
    28	
    29	    private Api(Db db) {
    30	        ReservationRepository reservations = new ReservationRepository();
    31	        MessageRepository messages = new MessageRepository();
    32	        this.db = db;
    33	        this.service = new ReservationService(db, reservations, messages);
    34	    }
    35	
    36	    public static Javalin create(Db db) {
    37	        return new Api(db).routes();
    38	    }
    39	
    40	    private Javalin routes() {
    41	        Javalin app = Javalin.create();
    42	        app.exception(BusinessException.class, (e, ctx) -> error(ctx, e.code().httpStatus(), e.code().name(), e.getMessage()));
    43	        app.exception(Exception.class, (e, ctx) -> {
    44	            e.printStackTrace();
    45	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    46	        });
    47	
    48	        app.get("/rooms", ctx -> json(ctx, 200, RoomCatalog.all().stream().map(r -> Map.of(
    49	                "number", r.number(), "type", r.type(), "capacity", r.capacity(),
    50	                "nightlyRate", r.nightlyRate())).toList()));
    51	        app.post("/reservations", ctx -> json(ctx, 201,
    52	                service.create(CreateReservationRequest.parse(mapper, ctx.body()))));
    53	        app.get("/reservations/{id}", ctx -> json(ctx, 200, service.get(id(ctx))));
    54	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, service.confirm(id(ctx))));
    55	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, service.cancel(id(ctx))));
    56	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, service.checkIn(id(ctx))));
    57	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, service.checkOut(id(ctx))));
    58	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, service.document(id(ctx))));
    59	        app.get("/messages", ctx -> json(ctx, 200, service.sentMessages()));
    60	
    61	        for (Report<?> report : Reports.all(new ReservationRepository())) {
    62	            app.get("/reports/" + report.name(), ctx -> {
    63	                String csv = db.inTransaction(c -> report.render(c, ctx.queryParam(report.parameter())));
    64	                ctx.status(200).contentType("text/csv; charset=utf-8").result(csv);
    65	            });
    66	        }
    67	        return app;
    68	    }
    69	
    70	    private static long id(Context ctx) {
    71	        String raw = ctx.pathParam("id");
    72	        try {
    73	            return Long.parseLong(raw);
    74	        } catch (NumberFormatException e) {
    75	            throw new BusinessException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + raw + " não existe");
    76	        }
    77	    }
    78	
    79	    private void json(Context ctx, int status, Object body) throws Exception {
    80	        ctx.status(status).contentType("application/json").result(mapper.writeValueAsString(body));
    81	    }
    82	
    83	    private void error(Context ctx, int status, String code, String message) {
    84	        try {
    85	            json(ctx, status, Map.of("error", code, "message", message));
    86	        } catch (Exception e) {
    87	            ctx.status(status).result(code);
    88	        }
    89	    }
    90	}
