    17	import java.sql.Connection;
    18	import java.sql.SQLException;
    19	import java.util.List;
    20	import java.util.function.Consumer;
    21	
    22	public class ReservationService {
    23	    private final Db db;
    24	    private final ReservationRepository reservations;
    25	    private final MessageRepository messages;
    26	
    27	    public ReservationService(Db db, ReservationRepository reservations, MessageRepository messages) {
    28	        this.db = db;
    29	        this.reservations = reservations;
    30	        this.messages = messages;
    31	    }
    32	
    33	    public Reservation create(NewReservation request) {
    34	        Room room = RoomCatalog.require(request.roomNumber());
    35	        if (request.guests() > room.capacity()) {
    36	            throw new BusinessException(ErrorCode.CAPACITY_EXCEEDED,
    37	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    38	        }
    39	        Quote quote = Quote.of(room, request.checkIn(), request.checkOut(), request.ratePlan());
    40	        Reservation pending = new Reservation(null, room.number(), request.guestName(), request.guestEmail(),
    41	                request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(), request.ratePlan(),
    42	                quote.nights(), quote.subtotal(), quote.discount(), quote.total(),
    43	                ReservationStatus.PENDING, Money.ZERO, null);
    44	        return db.inTransaction(c -> {
    45	            reservations.lockRoom(c, room.number());
    46	            if (reservations.hasActiveReservation(c, room.number(), request.checkIn(), request.checkOut())) {
    47	                throw new BusinessException(ErrorCode.ROOM_UNAVAILABLE,
    48	                        "O quarto " + room.number() + " já está reservado em alguma das noites");
    49	            }
    50	            return reservations.insert(c, pending);
    51	        });
    52	    }
    53	
    54	    public Reservation get(long id) {
    55	        return db.inTransaction(c -> reservations.find(c, id).orElseThrow(() -> notFound(id)));
    56	    }
    57	
    58	    public Reservation confirm(long id) {
    59	        return change(id, Reservation::confirm, (c, r) -> {
    60	            messages.save(c, Message.reservationConfirmed(r, Receipt.of(r)));
    61	        });
    62	    }
    63	
    64	    public Reservation cancel(long id) {
    65	        return change(id, Reservation::cancel, (c, r) -> { });
    66	    }
    67	
    68	    public Reservation checkIn(long id) {
    69	        return change(id, Reservation::registerCheckIn, (c, r) -> { });
    70	    }
    71	
    72	    public Receipt checkOut(long id) {
    73	        return Receipt.of(change(id, Reservation::registerCheckOut, (c, r) -> { }));
    74	    }
    75	
    76	    /** Segunda via: só existe para reserva paga. */
    77	    public Receipt document(long id) {
    78	        Reservation reservation = get(id);
    79	        if (!reservation.getStatus().isPaid()) {
    80	            throw new BusinessException(ErrorCode.OPERATION_NOT_ALLOWED,
    81	                    "A reserva " + id + " não tem pagamento, então não tem comprovante");
    82	        }
    83	        return Receipt.of(reservation);
    84	    }
    85	
    86	    public List<Message> sentMessages() {
    87	        return db.inTransaction(messages::findAll);
    88	    }
    89	
    90	    @FunctionalInterface
    91	    private interface SideEffect {
    92	        void run(Connection connection, Reservation reservation) throws SQLException;
    93	    }
    94	
    95	    /** A sequência é a mesma para toda mudança de situação: trava, aplica, grava, efeitos, devolve. */
    96	    private Reservation change(long id, Consumer<Reservation> transition, SideEffect sideEffect) {
    97	        return db.inTransaction(c -> {
    98	            Reservation reservation = reservations.findForUpdate(c, id).orElseThrow(() -> notFound(id));
    99	            transition.accept(reservation);
   100	            reservations.saveState(c, reservation);
   101	            sideEffect.run(c, reservation);
   102	            return reservation;
   103	        });
   104	    }
   105	
   106	    private static BusinessException notFound(long id) {
   107	        return new BusinessException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe");
   108	    }
   109	}
