     1	package br.com.mare.pousada.infra;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	
     6	import java.sql.Connection;
     7	import java.sql.SQLException;
     8	import java.sql.Statement;
     9	
    10	public class Db implements AutoCloseable {
    11	
    12	    @FunctionalInterface
    13	    public interface Work<T> {
    14	        T run(Connection connection) throws SQLException;
    15	    }
    16	
    17	    private static final String SCHEMA = """
    18	            CREATE TABLE IF NOT EXISTS reservations (
    19	                id BIGSERIAL PRIMARY KEY,
    20	                room_number INT NOT NULL,
    21	                guest_name TEXT NOT NULL,
    22	                guest_email TEXT NOT NULL,
    23	                guest_cpf TEXT NOT NULL,
    24	                check_in DATE NOT NULL,
    25	                check_out DATE NOT NULL,
    26	                guests INT NOT NULL,
    27	                rate_plan TEXT NOT NULL,
    28	                nights INT NOT NULL,
    29	                subtotal NUMERIC(12,2) NOT NULL,
    30	                discount NUMERIC(12,2) NOT NULL,
    31	                total NUMERIC(12,2) NOT NULL,
    32	                status TEXT NOT NULL,
    33	                amount_paid NUMERIC(12,2) NOT NULL DEFAULT 0,
    34	                refund NUMERIC(12,2)
    35	            );
    36	            CREATE INDEX IF NOT EXISTS reservations_room_dates ON reservations (room_number, check_in, check_out);
    37	            CREATE INDEX IF NOT EXISTS reservations_check_in ON reservations (check_in);
    38	            CREATE TABLE IF NOT EXISTS messages (
    39	                id BIGSERIAL PRIMARY KEY,
    40	                channel TEXT NOT NULL,
    41	                recipient TEXT NOT NULL,
    42	                subject TEXT NOT NULL,
    43	                body TEXT NOT NULL
    44	            );
    45	            """;
    46	
    47	    private final HikariDataSource dataSource;
    48	
    49	    public Db(String url, String user, String password) {
    50	        HikariConfig config = new HikariConfig();
    51	        config.setJdbcUrl(url);
    52	        config.setUsername(user);
    53	        config.setPassword(password);
    54	        config.setMaximumPoolSize(10);
    55	        config.setInitializationFailTimeout(60_000);
    56	        this.dataSource = new HikariDataSource(config);
    57	        createSchema();
    58	    }
    59	
    60	    private void createSchema() {
    61	        inTransaction(connection -> {
    62	            try (Statement statement = connection.createStatement()) {
    63	                statement.execute("SELECT pg_advisory_xact_lock(0)");
    64	                statement.execute(SCHEMA);
    65	            }
    66	            return null;
    67	        });
    68	    }
    69	
    70	    public <T> T inTransaction(Work<T> work) {
    71	        try (Connection connection = dataSource.getConnection()) {
    72	            connection.setAutoCommit(false);
    73	            try {
    74	                T result = work.run(connection);
    75	                connection.commit();
    76	                return result;
    77	            } catch (Throwable e) {
    78	                connection.rollback();
    79	                throw e;
    80	            }
    81	        } catch (SQLException e) {
    82	            throw new IllegalStateException("Erro de banco de dados", e);
    83	        }
    84	    }
    85	
    86	    @Override
    87	    public void close() {
    88	        dataSource.close();
    89	    }
    90	}
