    16	    public void save(Connection c, Message m) throws SQLException {
    17	        try (PreparedStatement s = c.prepareStatement(
    18	                "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?)")) {
    19	            s.setString(1, m.channel().name());
    20	            s.setString(2, m.to());
    21	            s.setString(3, m.subject());
    22	            s.setString(4, m.body());
    23	            s.executeUpdate();
    24	        }
    25	    }
    26	
    27	    public List<Message> findAll(Connection c) throws SQLException {
    28	        try (PreparedStatement s = c.prepareStatement("SELECT * FROM messages ORDER BY id");
    29	             ResultSet rs = s.executeQuery()) {
    30	            List<Message> result = new ArrayList<>();
    31	            while (rs.next()) {
    32	                result.add(new Message(rs.getLong("id"), MessageChannel.valueOf(rs.getString("channel")),
    33	                        rs.getString("recipient"), rs.getString("subject"), rs.getString("body")));
    34	            }
    35	            return result;
    36	        }
    37	    }
