    18	public class ReservationRepository {
    19	
    20	    /** Reservas de um quarto são serializadas por esta trava, até o fim da transação. */
    21	    public void lockRoom(Connection c, int roomNumber) throws SQLException {
    22	        try (PreparedStatement s = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    23	            s.setLong(1, roomNumber);
    24	            s.execute();
    25	        }
    26	    }
    27	
    28	    public boolean hasActiveReservation(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut)
    29	            throws SQLException {
    30	        try (PreparedStatement s = c.prepareStatement("""
    31	                SELECT 1 FROM reservations
    32	                WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?
    33	                LIMIT 1""")) {
    34	            s.setInt(1, roomNumber);
    35	            s.setDate(2, Date.valueOf(checkOut));
    36	            s.setDate(3, Date.valueOf(checkIn));
    37	            try (ResultSet rs = s.executeQuery()) {
    38	                return rs.next();
    39	            }
    40	        }
    41	    }
    42	
    43	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    44	        try (PreparedStatement s = c.prepareStatement("""
    45	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
    46	                    guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
    47	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    48	                RETURNING *""")) {
    49	            s.setInt(1, r.getRoomNumber());
    50	            s.setString(2, r.getGuestName());
    51	            s.setString(3, r.getGuestEmail());
    52	            s.setString(4, r.getGuestCpf());
    53	            s.setDate(5, Date.valueOf(r.getCheckIn()));
    54	            s.setDate(6, Date.valueOf(r.getCheckOut()));
    55	            s.setInt(7, r.getGuests());
    56	            s.setString(8, r.getRatePlan().name());
    57	            s.setInt(9, r.getNights());
    58	            s.setBigDecimal(10, r.getSubtotal());
    59	            s.setBigDecimal(11, r.getDiscount());
    60	            s.setBigDecimal(12, r.getTotal());
    61	            s.setString(13, r.getStatus().name());
    62	            s.setBigDecimal(14, r.getAmountPaid());
    63	            s.setBigDecimal(15, r.getRefund());
    64	            try (ResultSet rs = s.executeQuery()) {
    65	                rs.next();
    66	                return map(rs);
    67	            }
    68	        }
    69	    }
    70	
    71	    public Optional<Reservation> findForUpdate(Connection c, long id) throws SQLException {
    72	        try (PreparedStatement s = c.prepareStatement("SELECT * FROM reservations WHERE id = ? FOR UPDATE")) {
    73	            s.setLong(1, id);
    74	            try (ResultSet rs = s.executeQuery()) {
    75	                return rs.next() ? Optional.of(map(rs)) : Optional.empty();
    76	            }
    77	        }
    78	    }
    79	
    80	    public void saveState(Connection c, Reservation r) throws SQLException {
    81	        try (PreparedStatement s = c.prepareStatement(
    82	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    83	            s.setString(1, r.getStatus().name());
    84	            s.setBigDecimal(2, r.getAmountPaid());
    85	            s.setBigDecimal(3, r.getRefund());
    86	            s.setLong(4, r.getId());
