    15	/** Lê e valida o corpo do POST /reservations. */
    16	final class CreateReservationRequest {
    17	    private static final DateTimeFormatter DATE =
    18	            DateTimeFormatter.ofPattern("uuuu-MM-dd").withResolverStyle(ResolverStyle.STRICT);
    19	
    20	    private CreateReservationRequest() {
    21	    }
    22	
    23	    static NewReservation parse(ObjectMapper mapper, String body) {
    24	        JsonNode json;
    25	        try {
    26	            json = mapper.readTree(body);
    27	        } catch (Exception e) {
    28	            throw invalid("O corpo não é um JSON válido");
    29	        }
    30	        if (json == null || !json.isObject()) {
    31	            throw invalid("O corpo deve ser um objeto JSON");
    32	        }
    33	        LocalDate checkIn = date(json, "checkIn");
    34	        LocalDate checkOut = date(json, "checkOut");
    35	        int guests = integer(json, "guests");
    36	        NewReservation request = new NewReservation(integer(json, "roomNumber"), text(json, "guestName"),
    37	                text(json, "guestEmail"), text(json, "guestCpf"), checkIn, checkOut, guests, ratePlan(json));
    38	        if (!checkOut.isAfter(checkIn)) {
    39	            throw invalid("A saída deve ser depois da entrada");
    40	        }
    41	        if (guests < 1) {
    42	            throw invalid("É preciso pelo menos um hóspede");
    43	        }
    44	        return request;
    45	    }
    46	
    47	    private static String text(JsonNode json, String field) {
    48	        JsonNode node = json.get(field);
    49	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    50	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    51	        }
    52	        return node.asText();
    53	    }
    54	
    55	    private static int integer(JsonNode json, String field) {
    56	        JsonNode node = json.get(field);
    57	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    58	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    59	        }
    60	        return node.asInt();
    61	    }
    62	
    63	    private static LocalDate date(JsonNode json, String field) {
    64	        try {
    65	            return LocalDate.parse(text(json, field), DATE);
    66	        } catch (DateTimeParseException e) {
    67	            throw invalid("Data inválida em " + field + " (use 2027-07-10)");
    68	        }
    69	    }
