    30	        this.messages = messages;
    31	    }
    32	
    33	    public Reservation create(NewReservation request) {
    34	        Room room = RoomCatalog.require(request.roomNumber());
    35	        if (request.guests() > room.capacity()) {
    36	            throw new BusinessException(ErrorCode.CAPACITY_EXCEEDED,
    37	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    38	        }
    39	        Quote quote = Quote.of(room, request.checkIn(), request.checkOut(), request.ratePlan());
    40	        Reservation pending = new Reservation(null, room.number(), request.guestName(), request.guestEmail(),
    41	                request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(), request.ratePlan(),
    42	                quote.nights(), quote.subtotal(), quote.discount(), quote.total(),
    43	                ReservationStatus.PENDING, Money.ZERO, null);
    44	        return db.inTransaction(c -> {
    45	            reservations.lockRoom(c, room.number());
    46	            if (reservations.hasActiveReservation(c, room.number(), request.checkIn(), request.checkOut())) {
    47	                throw new BusinessException(ErrorCode.ROOM_UNAVAILABLE,
    48	                        "O quarto " + room.number() + " já está reservado em alguma das noites");
    49	            }
    50	            return reservations.insert(c, pending);
    51	        });
    52	    }
