    58	    public Reservation confirm(long id) {
    59	        return change(id, Reservation::confirm, (c, r) -> {
    60	            messages.save(c, Message.reservationConfirmed(r, Receipt.of(r)));
    61	        });
    62	    }
    63	
    64	    public Reservation cancel(long id) {
    65	        return change(id, Reservation::cancel, (c, r) -> { });
    66	    }
    67	
    68	    public Reservation checkIn(long id) {
    69	        return change(id, Reservation::registerCheckIn, (c, r) -> { });
    70	    }
    71	
    72	    public Receipt checkOut(long id) {
    73	        return Receipt.of(change(id, Reservation::registerCheckOut, (c, r) -> { }));
    74	    }
    75	
    76	    /** Segunda via: só existe para reserva paga. */
    77	    public Receipt document(long id) {
    78	        Reservation reservation = get(id);
    79	        if (!reservation.getStatus().isPaid()) {
    80	            throw new BusinessException(ErrorCode.OPERATION_NOT_ALLOWED,
    81	                    "A reserva " + id + " não tem pagamento, então não tem comprovante");
    82	        }
    83	        return Receipt.of(reservation);
