    94	
    95	    /** A sequência é a mesma para toda mudança de situação: trava, aplica, grava, efeitos, devolve. */
    96	    private Reservation change(long id, Consumer<Reservation> transition, SideEffect sideEffect) {
    97	        return db.inTransaction(c -> {
    98	            Reservation reservation = reservations.findForUpdate(c, id).orElseThrow(() -> notFound(id));
    99	            transition.accept(reservation);
   100	            reservations.saveState(c, reservation);
