     9	import java.time.format.ResolverStyle;
    10	import java.util.ArrayList;
    11	import java.util.List;
    12	import java.util.stream.Collectors;
    13	
    14	/**
    15	 * Todo relatório sai por aqui: título, cabeçalho, linhas, total. Mudar o jeito dos relatórios
    16	 * (por exemplo, uma linha final com a data em que foi tirado) é mudar só {@link #render}.
    17	 * Cada relatório define apenas o nome, o parâmetro e o conteúdo.
    18	 *
    19	 * @param <P> o período do relatório (uma noite, um mês)
    20	 */
    21	public abstract class Report<P> {
    22	    static final String ESTABLISHMENT = "Pousada Maré Alta";
    23	    static final DateTimeFormatter STRICT_DATE =
    24	            DateTimeFormatter.ofPattern("uuuu-MM-dd").withResolverStyle(ResolverStyle.STRICT);
    25	    static final DateTimeFormatter STRICT_MONTH =
    26	            DateTimeFormatter.ofPattern("uuuu-MM").withResolverStyle(ResolverStyle.STRICT);
    27	
    28	    /** Nome no título e no endereço: occupancy, revenue... */
    29	    public abstract String name();
    30	
    31	    /** Nome do parâmetro de consulta: date, month. */
    32	    public abstract String parameter();
    33	
    34	    protected abstract P parse(String raw);
    35	
    36	    protected abstract Table build(Connection connection, P period) throws SQLException;
    37	
    38	    public final String render(Connection connection, String rawPeriod) throws SQLException {
    39	        if (rawPeriod == null) {
    40	            throw invalid("Falta o parâmetro " + parameter());
    41	        }
    42	        P period = parse(rawPeriod);
    43	        Table table = build(connection, period);
    44	        List<List<String>> lines = new ArrayList<>();
    45	        lines.add(List.of(ESTABLISHMENT, name(), period.toString()));
    46	        lines.add(table.header());
    47	        lines.addAll(table.rows());
    48	        lines.add(table.total());
    49	        return lines.stream().map(Report::csvLine).collect(Collectors.joining("\n", "", "\n"));
    50	    }
    51	
    52	    protected static BusinessException invalid(String message) {
    53	        return new BusinessException(ErrorCode.INVALID_REQUEST, message);
    54	    }
    55	
    56	    private static String csvLine(List<String> cells) {
    57	        return cells.stream().map(Report::csvCell).collect(Collectors.joining(","));
    58	    }
    59	
    60	    private static String csvCell(String cell) {
    61	        boolean needsQuotes = cell.contains(",") || cell.contains("\"") || cell.contains("\n");
    62	        return needsQuotes ? '"' + cell.replace("\"", "\"\"") + '"' : cell;
    63	    }
    64	}
