    89	import java.util.UUID;
    90	
    91	import static org.junit.jupiter.api.Assertions.assertEquals;
    92	import static org.junit.jupiter.api.Assertions.assertTrue;
    93	import static org.junit.jupiter.api.Assumptions.assumeTrue;
    94	
    95	/** Roda contra o banco de DB_URL, num schema próprio que some no fim. */
    96	class ApiIntegrationTest {
    97	    static String url, user, password, schema;
    98	    static Db db;
    99	    static Javalin app;
   100	    static String base;
   101	    static final HttpClient http = HttpClient.newHttpClient();
   102	
   103	    @BeforeAll
   104	    static void start() throws Exception {
   105	        url = System.getenv("DB_URL");
   106	        user = System.getenv("DB_USER");
   107	        password = System.getenv("DB_PASSWORD");
   108	        assumeTrue(url != null, "DB_URL não definido");
   109	        schema = "test_" + UUID.randomUUID().toString().replace("-", "");
   110	        try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
   111	            s.execute("CREATE SCHEMA " + schema);
   112	        }
   113	        db = new Db(url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema, user, password);
   114	        app = Api.create(db).start(0);
   115	        base = "http://localhost:" + app.port();
   116	    }
   117	
   118	    @AfterAll
   119	    static void stop() throws Exception {
   120	        if (app != null) app.stop();
   121	        if (db != null) db.close();
   122	        if (schema != null) {
   123	            try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
   124	                s.execute("DROP SCHEMA " + schema + " CASCADE");
   125	            }
   126	        }
   127	    }
   128	
   129	    static HttpResponse<String> call(String method, String path, String body) throws Exception {
   130	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path)).header("Content-Type", "application/json");
   131	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
   132	        return http.send(b.build(), HttpResponse.BodyHandlers.ofString());
   133	    }
   134	
   135	    static String reservation(int room, String in, String out, int guests, String plan) {
   136	        return """
   137	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"carla@x.com","guestCpf":"111.222.333-44",
